import 'dart:async';
import 'dart:io';
import 'dart:typed_data';
import 'package:camera/camera.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:path_provider/path_provider.dart';
import 'package:securec/modules/dashboard/models/message_model.dart';
import '../../settings/widgets/profile_crop_screen.dart';

enum CameraMode { photo, video }

class ChatCameraView extends StatefulWidget {
  final CameraMode initialMode;

  const ChatCameraView({super.key, this.initialMode = CameraMode.photo});

  @override
  State<ChatCameraView> createState() => _ChatCameraViewState();
}

class _ChatCameraViewState extends State<ChatCameraView>
    with WidgetsBindingObserver {
  static const MethodChannel _videoMergerChannel = MethodChannel(
    'com.securec/video_merger',
  );

  List<CameraDescription> _cameras = [];
  CameraController? _controller;

  int _selectedCameraIndex = 0;
  bool _isInitialized = false;
  bool _isRecording = false;
  bool _isFlashOn = false;
  bool _isStartingRecording = false;
  bool _isProcessingRecording = false;

  CameraMode _mode = CameraMode.photo;

  Timer? _recordTimer;
  Duration _recordDuration = Duration.zero;
  DateTime? _recordingStartTime;
  Duration _accumulatedDuration = Duration.zero;

  List<File> _videoSegments = [];
  List<Map<String, dynamic>> _segmentInfo = [];
  int _recordStartTick = 0;

  bool _isSwitchingCamera = false;

  bool _isFrontCamera() {
    if (_cameras.isEmpty || _selectedCameraIndex >= _cameras.length) {
      return false;
    }
    return _cameras[_selectedCameraIndex].lensDirection ==
        CameraLensDirection.front;
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _mode = widget.initialMode;
    _initCameras();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _recordTimer?.cancel();
    _cleanupVideoSegments();
    _controller?.dispose().catchError((e) {
      print('Error disposing camera in dispose: $e');
    });
    _controller = null;
    super.dispose();
  }

  void _cleanupVideoSegments() {
    for (var segment in _videoSegments) {
      try {
        if (segment.existsSync()) {
          segment.deleteSync();
        }
      } catch (e) {
        print('Error cleaning up video segment: $e');
      }
    }
    _videoSegments.clear();
    _segmentInfo.clear();
  }

  Future<File?> _buildFinalVideoFile() async {
    if (_videoSegments.isEmpty) {
      print('ERROR: No video segments to build final file');
      return null;
    }

    if (_videoSegments.length == 1) {
      final singleFile = _videoSegments.first;
      if (!singleFile.existsSync()) {
        print('ERROR: Single video segment does not exist: ${singleFile.path}');
        return null;
      }
      final fileSize = singleFile.lengthSync();
      if (fileSize == 0) {
        print('ERROR: Single video segment is empty');
        return null;
      }
      print(
        '=== Using single video segment: ${singleFile.path} (${fileSize} bytes) ===',
      );
      return singleFile;
    }

    print('=== Multiple segments detected, merging... ===');
    return _mergeVideoSegments();
  }

  Future<File?> _mergeVideoSegments() async {
    if (_videoSegments.length <= 1) {
      return _videoSegments.isNotEmpty ? _videoSegments.first : null;
    }

    print('=== Starting video merge: ${_videoSegments.length} segments ===');
    print('Segment info count: ${_segmentInfo.length}');

    try {
      final tempDir = await getTemporaryDirectory();
      final timestamp = DateTime.now().millisecondsSinceEpoch;
      final outputPath = '${tempDir.path}/merged_$timestamp.mp4';

      // Filter segment info to only include existing files
      final validSegmentInfo = _segmentInfo.where((info) {
        final path = info['path'] as String?;
        if (path == null) {
          print('Warning: Segment info missing path');
          return false;
        }
        final file = File(path);
        if (!file.existsSync()) {
          print('Warning: Segment file does not exist: $path');
          return false;
        }
        print('Valid segment: $path (${file.lengthSync()} bytes)');
        return true;
      }).toList();

      print('Valid segments: ${validSegmentInfo.length}');

      if (validSegmentInfo.length <= 1) {
        print(
          'Only ${validSegmentInfo.length} valid segments, returning single file',
        );
        return validSegmentInfo.isNotEmpty
            ? File(validSegmentInfo.first['path'] as String)
            : null;
      }

      print('Calling native merge with ${validSegmentInfo.length} segments');
      print('Output path: $outputPath');

      final mergedPath = await _videoMergerChannel.invokeMethod<String>(
        'mergeSegments',
        {'segments': validSegmentInfo, 'outputPath': outputPath},
      );

      print('Native merge returned: $mergedPath');

      if (mergedPath == null || mergedPath.isEmpty) {
        print('ERROR: Video merge channel returned null or empty path');
        throw Exception('Merge returned null path');
      }

      final mergedFile = File(mergedPath);
      if (!mergedFile.existsSync()) {
        print('ERROR: Merged file does not exist at: $mergedPath');
        throw Exception('Merged file not found');
      }

      final fileSize = mergedFile.lengthSync();
      print('=== Merge successful! File size: $fileSize bytes ===');

      if (fileSize == 0) {
        print('ERROR: Merged file is empty');
        throw Exception('Merged file is empty');
      }

      return mergedFile;
    } on MissingPluginException catch (e) {
      print('ERROR: Video merge plugin missing: $e');
      rethrow;
    } on PlatformException catch (e) {
      print('ERROR: Video merge platform exception: ${e.message}');
      print('Error code: ${e.code}, details: ${e.details}');
      rethrow;
    } catch (e, stackTrace) {
      print('ERROR: Unexpected error merging video segments: $e');
      print('Stack trace: $stackTrace');
      rethrow;
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (_controller == null) return;

    if (state == AppLifecycleState.inactive) {
      _controller?.dispose();
    } else if (state == AppLifecycleState.resumed) {
      _onNewCamera(_cameras[_selectedCameraIndex]);
    }
  }

  Future<void> _initCameras() async {
    try {
      _cameras = await availableCameras();
      if (_cameras.isNotEmpty) {
        await _onNewCamera(_cameras[_selectedCameraIndex]);
      }
    } catch (_) {}
  }

  Future<void> _onNewCamera(CameraDescription cam) async {
    final old = _controller;
    _controller = null;

    if (old != null) {
      try {
        await old.dispose().timeout(
          Duration(seconds: 2),
          onTimeout: () {
            print('Camera dispose timeout in _onNewCamera, continuing...');
          },
        );
        await Future.delayed(Duration(milliseconds: 100));
      } catch (e) {
        print('Error disposing old camera in _onNewCamera: $e');
      }
    }

    if (!mounted) return;

    final controller = CameraController(
      cam,
      ResolutionPreset.high,
      enableAudio: true,
    );

    _controller = controller;

    try {
      await controller.initialize();

      // Ensure flash is off for front camera or reset flash state
      final isFrontCamera = cam.lensDirection == CameraLensDirection.front;
      if (isFrontCamera && _isFlashOn) {
        try {
          await controller.setFlashMode(FlashMode.off);
          if (mounted) {
            setState(() {
              _isInitialized = true;
              _isFlashOn = false;
            });
          }
        } catch (e) {
          print('Error setting flash off for front camera: $e');
          if (mounted) {
            setState(() {
              _isInitialized = true;
              _isFlashOn = false;
            });
          }
        }
      } else {
        // Ensure flash is off initially for back camera too
        try {
          await controller.setFlashMode(FlashMode.off);
          if (mounted) {
            setState(() {
              _isInitialized = true;
              _isFlashOn = false;
            });
          }
        } catch (e) {
          print('Error setting flash off: $e');
          if (mounted) {
            setState(() => _isInitialized = true);
          }
        }
      }
    } catch (e) {
      print('Error initializing camera: $e');
      if (mounted) {
        setState(() => _isInitialized = false);
      }
    }
  }

  Future<void> _takePhoto() async {
    if (_controller == null) return;

    final xfile = await _controller!.takePicture();
    if (!mounted) return;

    // Turn off flash after capturing image
    if (_isFlashOn && _controller != null) {
      try {
        await _controller!.setFlashMode(FlashMode.off);
        if (mounted) {
          setState(() => _isFlashOn = false);
        }
      } catch (e) {
        print('Error turning off flash after photo: $e');
      }
    }

    final capturedFile = File(xfile.path);

    // Show preview screen with crop option
    final result = await Navigator.push<Map<String, dynamic>>(
      context,
      MaterialPageRoute(
        fullscreenDialog: true,
        builder: (context) => _ImagePreviewScreen(imageFile: capturedFile),
      ),
    );

    if (!mounted) return;

    if (result != null && result['file'] != null) {
      // Forward the action to parent so it can skip second preview
      Navigator.pop(context, {
        'file': result['file'] as File,
        'type': MediaType.image,
        'action': result['action'], // Forward the action
      });
    } else {
      // User cancelled, stay on camera
    }
  }

  Future<void> _toggleRecording() async {
    if (_controller == null || _isProcessingRecording) return;

    // Prevent multiple simultaneous calls
    _isProcessingRecording = true;

    // Immediately update UI to show loading in button
    if (mounted) {
      setState(() {});
    }

    if (_isRecording) {
      _recordTimer?.cancel();
      try {
        if (_recordingStartTime != null) {
          _recordDuration =
              _accumulatedDuration +
              DateTime.now().difference(_recordingStartTime!);
        } else {
          _recordDuration = _accumulatedDuration;
        }

        if (_controller!.value.isRecordingVideo) {
          final file = await _controller!.stopVideoRecording();
          final filePath = file.path;

          // Wait a bit to ensure the video file is fully written
          await Future.delayed(Duration(milliseconds: 200));

          final segmentFile = File(filePath);
          if (!segmentFile.existsSync()) {
            print('ERROR: Video segment file does not exist: $filePath');
            throw Exception('Video segment file not found');
          }

          final fileSize = segmentFile.lengthSync();
          if (fileSize == 0) {
            print('ERROR: Video segment file is empty: $filePath');
            throw Exception('Video segment file is empty');
          }

          _videoSegments.add(segmentFile);
          // Native code only needs path and isFrontCamera
          // Orientation is determined from video file metadata
          _segmentInfo.add({
            "path": filePath,
            "isFrontCamera": _isFrontCamera(),
          });
        }

        print('=== Building final video file ===');
        print('Video segments count: ${_videoSegments.length}');
        print('Segment info count: ${_segmentInfo.length}');

        final finalVideo = await _buildFinalVideoFile();

        if (finalVideo == null) {
          print('ERROR: finalVideo is null');
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('Error: Could not create video file'),
                backgroundColor: Colors.red,
              ),
            );
          }
          setState(() {
            _isRecording = false;
            _recordDuration = Duration.zero;
            _recordingStartTime = null;
            _accumulatedDuration = Duration.zero;
            _isProcessingRecording = false;
          });
          _cleanupVideoSegments();
          return;
        }

        // Verify final video file exists and has content
        if (!finalVideo.existsSync()) {
          print('ERROR: Final video file does not exist: ${finalVideo.path}');
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('Error: Video file not found'),
                backgroundColor: Colors.red,
              ),
            );
          }
          setState(() {
            _isRecording = false;
            _recordDuration = Duration.zero;
            _recordingStartTime = null;
            _accumulatedDuration = Duration.zero;
            _isProcessingRecording = false;
          });
          _cleanupVideoSegments();
          return;
        }

        final fileSize = finalVideo.lengthSync();
        if (fileSize == 0) {
          print('ERROR: Final video file is empty');
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('Error: Video file is empty'),
                backgroundColor: Colors.red,
              ),
            );
          }
          setState(() {
            _isRecording = false;
            _recordDuration = Duration.zero;
            _recordingStartTime = null;
            _accumulatedDuration = Duration.zero;
            _isProcessingRecording = false;
          });
          _cleanupVideoSegments();
          return;
        }

        print(
          '=== Final video ready: ${finalVideo.path} (${fileSize} bytes) ===',
        );

        setState(() {
          _isRecording = false;
          _recordDuration = Duration.zero;
          _recordingStartTime = null;
          _accumulatedDuration = Duration.zero;
          _isProcessingRecording = false;
        });

        _videoSegments.clear();
        _segmentInfo.clear();
        _recordStartTick = 0;

        if (mounted) {
          Navigator.pop(context, {'file': finalVideo, 'type': MediaType.video});
        }
      } catch (e, stackTrace) {
        print('ERROR stopping video recording: $e');
        print('Stack trace: $stackTrace');
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Error processing video: ${e.toString()}'),
              backgroundColor: Colors.red,
              duration: const Duration(seconds: 5),
            ),
          );
        }
        setState(() {
          _isRecording = false;
          _recordDuration = Duration.zero;
          _recordingStartTime = null;
          _accumulatedDuration = Duration.zero;
          _isProcessingRecording = false;
        });
        _cleanupVideoSegments();
      }
      return;
    }

    try {
      setState(() {
        _isStartingRecording = true;
      });

      _videoSegments.clear();
      _segmentInfo.clear();
      _recordStartTick = 0;
      _accumulatedDuration = Duration.zero;

      // Ensure flash is off for front camera before starting video recording
      if (_isFrontCamera() && _isFlashOn) {
        try {
          await _controller!.setFlashMode(FlashMode.off);
          if (mounted) {
            setState(() => _isFlashOn = false);
          }
        } catch (e) {
          print('Error turning off flash before video recording: $e');
        }
      }

      await _controller!.startVideoRecording();

      _recordingStartTime = DateTime.now();

      _recordTimer = Timer.periodic(Duration(milliseconds: 100), (timer) {
        if (mounted && _isRecording) {
          if (_recordingStartTime != null) {
            setState(() {
              _recordDuration =
                  _accumulatedDuration +
                  DateTime.now().difference(_recordingStartTime!);
            });
          }
        } else if (!_isRecording) {
          timer.cancel();
        }
      });

      setState(() {
        _isRecording = true;
        _isStartingRecording = false;
        _isProcessingRecording = false;
      });
    } catch (e) {
      print('Error starting video recording: $e');
      setState(() {
        _isRecording = false;
        _isStartingRecording = false;
        _recordingStartTime = null;
        _accumulatedDuration = Duration.zero;
        _isProcessingRecording = false;
      });
      _videoSegments.clear();
    }
  }

  Future<void> _switchCamera() async {
    if (_cameras.length < 2) return;

    // Prevent multiple simultaneous switch attempts
    if (_isSwitchingCamera) {
      print('Camera switch already in progress, ignoring...');
      return;
    }

    _isSwitchingCamera = true;

    // Save recording state
    final bool wasRecording = _isRecording;

    try {
      // Save the current camera index before switching
      final previousCameraIndex = _selectedCameraIndex;
      final wasFrontCamera =
          _cameras[previousCameraIndex].lensDirection ==
          CameraLensDirection.front;

      print('=== Starting camera switch ===');
      print('Was recording: $wasRecording');
      print('Previous camera: ${wasFrontCamera ? "FRONT" : "BACK"}');

      // If recording, save current segment before switching
      if (_isRecording && _controller != null) {
        try {
          if (_controller!.value.isRecordingVideo) {
            print('Stopping current recording segment...');
            final file = await _controller!.stopVideoRecording();
            final filePath = file.path;

            // Wait a bit to ensure the video file is fully written
            await Future.delayed(Duration(milliseconds: 200));

            final segmentFile = File(filePath);
            if (!segmentFile.existsSync()) {
              print('ERROR: Saved segment file does not exist: $filePath');
            } else {
              final fileSize = segmentFile.lengthSync();
              if (fileSize == 0) {
                print('ERROR: Saved segment file is empty: $filePath');
              } else {
                print('Segment saved: $filePath (${fileSize} bytes)');

                _videoSegments.add(segmentFile);
                _segmentInfo.add({
                  "path": filePath,
                  "isFrontCamera": wasFrontCamera,
                });
              }
            }

            if (_recordingStartTime != null) {
              _accumulatedDuration += DateTime.now().difference(
                _recordingStartTime!,
              );
              _recordingStartTime = null;
              print('Accumulated duration: ${_format(_accumulatedDuration)}');
            }
          }
        } catch (e) {
          print('Error saving segment before camera switch: $e');
          // Don't return - continue with camera switch even if segment save failed
        }
      }

      // Calculate next camera index
      _selectedCameraIndex = (_selectedCameraIndex + 1) % _cameras.length;
      final newCameraIsfront =
          _cameras[_selectedCameraIndex].lensDirection ==
          CameraLensDirection.front;

      print('Switching to: ${newCameraIsfront ? "FRONT" : "BACK"} camera');

      // Set initialized to false before disposing old controller to prevent black screen
      if (mounted) {
        setState(() {
          _isInitialized = false;
        });
      }

      // Dispose old controller
      final oldController = _controller;
      _controller = null;

      if (oldController != null) {
        try {
          await oldController.dispose().timeout(
            Duration(seconds: 2),
            onTimeout: () {
              print('Camera dispose timeout, continuing...');
            },
          );
          await Future.delayed(Duration(milliseconds: 50));
        } catch (e) {
          print('Error disposing old camera: $e');
        }
      }

      if (!mounted) {
        _isSwitchingCamera = false;
        return;
      }

      // Initialize new controller
      final newController = CameraController(
        _cameras[_selectedCameraIndex],
        ResolutionPreset.high,
        enableAudio: true,
      );

      _controller = newController;

      print('Initializing new camera controller...');
      await newController.initialize();

      print('New camera controller initialized');

      // Handle flash state based on camera direction
      final isFrontCamera = newCameraIsfront;

      if (isFrontCamera) {
        // Front camera doesn't support flash, turn it off
        try {
          await newController.setFlashMode(FlashMode.off);
          if (mounted) {
            setState(() {
              _isFlashOn = false;
            });
          }
        } catch (e) {
          print('Error setting flash off for front camera: $e');
          if (mounted) {
            setState(() {
              _isFlashOn = false;
            });
          }
        }
      } else {
        // Back camera - preserve flash state if it was on
        if (_isFlashOn && !wasFrontCamera) {
          // Flash was on and we're switching between back cameras, preserve it
          try {
            await newController.setFlashMode(FlashMode.torch);
          } catch (e) {
            print('Error preserving flash state: $e');
            try {
              await newController.setFlashMode(FlashMode.off);
              if (mounted) {
                setState(() {
                  _isFlashOn = false;
                });
              }
            } catch (e2) {
              print('Error turning off flash: $e2');
            }
          }
        } else {
          // Flash was off or we switched from front camera, ensure it's off
          try {
            await newController.setFlashMode(FlashMode.off);
            if (mounted && wasFrontCamera) {
              setState(() {
                _isFlashOn = false;
              });
            }
          } catch (e) {
            print('Error setting flash off: $e');
          }
        }
      }

      if (!mounted) {
        _controller?.dispose().catchError((e) {
          print('Error disposing new camera after unmount: $e');
        });
        _controller = null;
        _isSwitchingCamera = false;
        return;
      }

      // Update UI
      if (mounted) {
        setState(() {
          _isInitialized = true;
        });
      }

      // If was recording, resume recording after camera stabilizes
      if (wasRecording && _controller != null && _isInitialized) {
        print('Resuming recording after camera switch...');
        // Small delay to ensure camera preview is stable
        await Future.delayed(Duration(milliseconds: 150));

        if (!mounted || _controller == null) {
          print(
            'Context unmounted or controller null, cannot resume recording',
          );
          _isSwitchingCamera = false;
          return;
        }

        try {
          await _controller!.startVideoRecording();
          _recordingStartTime = DateTime.now();

          print('Recording resumed successfully');
          print('Total segments so far: ${_videoSegments.length}');

          // Update UI to show accumulated time
          if (mounted) {
            setState(() {
              _recordDuration = _accumulatedDuration;
            });
          }
        } catch (e) {
          print('ERROR: Failed to resume recording after camera switch: $e');
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text('Failed to resume recording: ${e.toString()}'),
                backgroundColor: Colors.red,
              ),
            );
            setState(() {
              _isRecording = false;
              _recordDuration = Duration.zero;
              _recordingStartTime = null;
              _accumulatedDuration = Duration.zero;
            });
          }
          _cleanupVideoSegments();
        }
      }

      print('=== Camera switch completed ===');
    } catch (e) {
      print('ERROR: Camera switch failed: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Camera switch failed: ${e.toString()}'),
            backgroundColor: Colors.red,
          ),
        );

        if (!wasRecording) {
          setState(() => _isInitialized = false);
        }
      }

      // Try to reinitialize camera
      try {
        if (_controller != null) {
          await _controller!.dispose();
        }
        _controller = null;
        if (mounted && _cameras.isNotEmpty) {
          await _onNewCamera(_cameras[_selectedCameraIndex]);
        }
      } catch (reinitError) {
        print('Error reinitializing camera: $reinitError');
      }
    } finally {
      _isSwitchingCamera = false;
      print('Camera switch lock released');
    }
  }

