import Foundation
import AVFoundation

final class VideoSegmentMerger {

    static let shared = VideoSegmentMerger()

    private init() {}

    // MARK: - Public API

    func mergeSegments(
        segments: [[String: Any]],
        outputPath: String
    ) throws -> String {

        var normalizedPaths: [String] = []

        for (index, segment) in segments.enumerated() {
            guard let path = segment["path"] as? String else {
                throw error("Segment[\(index)] missing path")
            }

            let isFrontCamera = segment["isFrontCamera"] as? Bool ?? false

            let normalized = try normalizeSegment(
                input: path,
                isFrontCamera: isFrontCamera
            )
            normalizedPaths.append(normalized)
        }

        try mergeNormalizedSegments(
            segments: normalizedPaths,
            output: outputPath
        )

        return outputPath
    }

    // MARK: - Normalization

    private func normalizeSegment(
        input: String,
        isFrontCamera: Bool
    ) throws -> String {

        let inputURL = URL(fileURLWithPath: input)
        let asset = AVAsset(url: inputURL)

        guard let videoTrack = asset.tracks(withMediaType: .video).first else {
            throw error("No video track found")
        }

        let composition = AVMutableComposition()
        let compTrack = composition.addMutableTrack(
            withMediaType: .video,
            preferredTrackID: kCMPersistentTrackID_Invalid
        )!

        try compTrack.insertTimeRange(
            CMTimeRange(start: .zero, duration: asset.duration),
            of: videoTrack,
            at: .zero
        )

        let videoComposition = AVMutableVideoComposition()
        videoComposition.renderSize = CGSize(width: 1080, height: 1920)
        videoComposition.frameDuration = CMTime(value: 1, timescale: 30)

        let instruction = AVMutableVideoCompositionInstruction()
        instruction.timeRange = CMTimeRange(start: .zero, duration: asset.duration)

        let layerInstruction = AVMutableVideoCompositionLayerInstruction(assetTrack: compTrack)

        var transform = videoTrack.preferredTransform

        // 🎥 Front camera flip handled here
        if isFrontCamera {
            transform = transform.scaledBy(x: -1, y: 1)
            transform = transform.translatedBy(x: videoTrack.naturalSize.width, y: 0)
        }

        layerInstruction.setTransform(transform, at: .zero)
        instruction.layerInstructions = [layerInstruction]
        videoComposition.instructions = [instruction]

        let outputURL = tempURL(prefix: "norm")
        try export(asset: composition, videoComposition: videoComposition, output: outputURL)

        return outputURL.path
    }

    // MARK: - Merge

    private func mergeNormalizedSegments(
        segments: [String],
        output: String
    ) throws {

        let composition = AVMutableComposition()
        let videoTrack = composition.addMutableTrack(
            withMediaType: .video,
            preferredTrackID: kCMPersistentTrackID_Invalid
        )!

        var currentTime = CMTime.zero

        for path in segments {
            let asset = AVAsset(url: URL(fileURLWithPath: path))
            let assetTrack = asset.tracks(withMediaType: .video).first!

            try videoTrack.insertTimeRange(
                CMTimeRange(start: .zero, duration: asset.duration),
                of: assetTrack,
                at: currentTime
            )

            currentTime = CMTimeAdd(currentTime, asset.duration)
        }

        let outputURL = URL(fileURLWithPath: output)
        try export(asset: composition, videoComposition: nil, output: outputURL)
    }

    // MARK: - Export Helper

    private func export(
        asset: AVAsset,
        videoComposition: AVVideoComposition?,
        output: URL
    ) throws {

        if FileManager.default.fileExists(atPath: output.path) {
            try FileManager.default.removeItem(at: output)
        }

        let exporter = AVAssetExportSession(
            asset: asset,
            presetName: AVAssetExportPresetHighestQuality
        )!

        exporter.outputURL = output
        exporter.outputFileType = .mp4
        exporter.videoComposition = videoComposition

        let semaphore = DispatchSemaphore(value: 0)
        var exportError: Error?

        exporter.exportAsynchronously {
            if exporter.status != .completed {
                exportError = exporter.error
            }
            semaphore.signal()
        }

        semaphore.wait()

        if let error = exportError {
            throw error
        }
    }

    // MARK: - Helpers

    private func tempURL(prefix: String) -> URL {
        let name = "\(prefix)_\(UUID().uuidString).mp4"
        return FileManager.default.temporaryDirectory.appendingPathComponent(name)
    }

    private func error(_ message: String) -> NSError {
        NSError(domain: "VideoSegmentMerger", code: -1,
                userInfo: [NSLocalizedDescriptionKey: message])
    }
}

